quality-prompt/index.__content:
import request from '@/utils/request';

// ==================== 类型定义 ====================

/**
 * 全局Prompt
 */
export interface GlobalPrompt {
  id: string;
  name: string;
  content: string;
  applicable_scenarios: string;
  enabled: number;
  version: number;
  platform_id: string;
  platform_name?: string;
  sort: number;
  created_by: string;
  created_at: string;
  updated_at: string;
  [key: string]: any;
}

/**
 * 部门Prompt
 */
export interface DepartmentPrompt {
  id: string;
  name: string;
  content: string;
  applicable_scenarios: string;
  enabled: number;
  version: number;
  platform_id: string;
  platform_name?: string;
  dept_id: string;
  dept_name?: string;
  parent_global_prompt_id?: string;
  parent_global_prompt_name?: string;
  sort: number;
  created_by: string;
  created_at: string;
  updated_at: string;
  [key: string]: any;
}

/**
 * Prompt模板
 */
export interface PromptTemplate {
  id: string;
  name: string;
  content: string;
  category: string;
  industry: string;
  description?: string;
  is_builtin: number;
  created_by?: string;
  created_at: string;
  updated_at: string;
  [key: string]: any;
}

/**
 * 版本记录
 */
export interface VersionRecord {
  id: string;
  prompt_id: string;
  prompt_type: 'global' | 'department';
  version: number;
  content: string;
  applicable_scenarios: string;
  change_description?: string;
  modified_by: string;
  modified_by_name?: string;
  modified_at: string;
  [key: string]: any;
}

/**
 * 审计日志
 */
export interface AuditLog {
  id: string;
  operation_type: string;
  operator_id: string;
  operator_name: string;
  timestamp: string;
  prompt_id: string;
  prompt_name: string;
  prompt_type: 'global' | 'department';
  before_content?: string;
  after_content?: string;
  reason?: string;
  ip_address?: string;
  [key: string]: any;
}

/**
 * 查询参数
 */
export interface QueryPromptsParams {
  keyword?: string;
  enabled?: number;
  platform_id?: string;
  dept_id?: string;
  page?: number;
  pageSize?: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
}

/**
 * 保存全局Prompt DTO
 */
export interface SaveGlobalPromptDto {
  name: string;
  content: string;
