    request.delete<void>(`/quality-prompts/templates/${id}`),

  /**
   * 获取模板分类列表
   */
  getTemplateCategories: () =>
    request.get<string[]>('/quality-prompts/templates/categories'),

  /**
   * 获取模板行业列表
